    elif disp_pct >= 0.45 and (0.25 <= cur_breadth <= 0.80):
        gross_target = 0.60
    else:
        gross_target = 0.35

    valid_n = len(score)
    max_side = valid_n // 2
    if max_side < 1:
        return weights

    desired = int(math.ceil(0.5 * gross_target / 0.02)) if gross_target > 0 else 0
    desired = max(1, desired)
    n_side = min(25, desired, max_side)
    if n_side < 1:
        return weights

    gross = min(gross_target, 0.04 * n_side)
    if gross <= 1e-12:
        return weights

    w = gross / (2.0 * n_side)
    if w > 0.02 + 1e-15:
        w = 0.02
        gross = 2.0 * n_side * w

    sorted_scores = score.sort_values(kind='mergesort')
    longs = list(sorted_scores.index[:n_side])
    shorts = list(sorted_scores.index[-n_side:])

    if set(longs) & set(shorts):
        n_side = min(n_side, valid_n // 2)
        if n_side < 1:
            return weights
        w = gross / (2.0 * n_side)
        longs = list(sorted_scores.index[:n_side])
        shorts = list(sorted_scores.index[-n_side:])

    for t in longs:
        weights.loc[t] = w
    for t in shorts:
        weights.loc[t] = -w

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0)
    weights = weights.clip(-0.02, 0.02)

    gross_actual = weights.abs().sum()
    if gross_actual > 1.0 + 1e-12:
        weights = weights * (1.0 / gross_actual)

    return weights

import numpy as np
import pandas as pd
import math


def _get_field(history, name):
    df = history.get(name)
    if df is None or not isinstance(df, pd.DataFrame):
        return None
    return df


def generate_weights(history, universe):
    universe = pd.Index(universe)
    weights = pd.Series(0.0, index=universe, dtype=float)
    if len(universe) == 0:
        return weights

    prices = _get_field(history, 'adjusted_close')
    if prices is None:
        prices = _get_field(history, 'close')
    if prices is None or prices.empty:
        return weights

    cols = [t for t in universe if t in prices.columns]
    if len(cols) < 2:
        return weights

    px = prices.loc[:, cols].tail(140).astype(float)
    if len(px) < 3:
        return weights

    elig = _get_field(history, 'eligible')
    elig_last = None
    if elig is not None and not elig.empty:
        ecols = [t for t in cols if t in elig.columns]
        if ecols:
            e = elig.loc[:, ecols].tail(1)
            elig_last = e.iloc[-1].reindex(cols)

    sig_px = px.tail(30)
    last = sig_px.iloc[-1]

    if len(sig_px) >= 6:
        ret5 = last / sig_px.iloc[-6] - 1.0
    else:
        ret5 = last / sig_px.iloc[0] - 1.0

    ret20 = None
    if len(sig_px) >= 21:
        ret20 = last / sig_px.iloc[-21] - 1.0

    mask = last.notna() & (last > 0) & ret5.notna()
    mask &= np.isfinite(ret5)
    if elig_last is not None:
        em = elig_last.fillna(True).astype(bool)
        mask &= em

    candidates = [t for t in cols if bool(mask.get(t, False))]
    if len(candidates) < 2:
        return weights

    r5 = ret5.reindex(candidates).astype(float)
    rank5 = r5.rank(method='average', pct=True)

    if ret20 is not None:
        r20 = ret20.reindex(candidates).astype(float)
        rank20 = r20.rank(method='average', pct=True).fillna(0.5)
        score = -(0.75 * rank5 + 0.25 * rank20)
    else:
        score = -rank5

    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 2:
        return weights

    rets = px.pct_change()
    valid_counts = rets.notna().sum(axis=1)
    disp = rets.std(axis=1, ddof=0)
    breadth = (rets > 0).sum(axis=1) / valid_counts.replace(0, np.nan)
    mkt = rets.mean(axis=1)

    cur_disp = disp.iloc[-1]
    cur_breadth = breadth.iloc[-1]

    if not np.isfinite(cur_disp):
        cur_disp = disp.dropna().iloc[-1] if disp.notna().any() else np.nan
    if not np.isfinite(cur_breadth):
        cur_breadth = breadth.dropna().iloc[-1] if breadth.notna().any() else 0.5

    if np.isfinite(cur_disp):
        hist_disp = disp.iloc[:-1].dropna().tail(120)
        if len(hist_disp) >= 20:
            disp_pct = float((hist_disp <= cur_disp).mean())
        else:
            disp_pct = 0.5
    else:
        disp_pct = 0.5

    mkt_vol_series = mkt.rolling(20, min_periods=10).std(ddof=0)
    cur_mvol = mkt_vol_series.iloc[-1]
    if np.isfinite(cur_mvol):
        hist_mvol = mkt_vol_series.iloc[:-1].dropna().tail(120)
        if len(hist_mvol) >= 20:
            mvol_pct = float((hist_mvol <= cur_mvol).mean())
        else:
            mvol_pct = 0.5
    else:
        mvol_pct = 0.5

    if not np.isfinite(cur_breadth):
        cur_breadth = 0.5

    risk_off = (cur_breadth < 0.25) or (mvol_pct >= 0.90 and cur_breadth < 0.40)
    high_disp = disp_pct >= 0.65
    moderate_breadth = (0.35 <= cur_breadth <= 0.70)

    if risk_off:
        gross_target = 0.25
    elif high_disp or moderate_breadth:
        gross_target = 1.0
    elif disp_pct >= 0.45 and (0.25 <= cur_breadth <= 0.80):
        gross_target = 0.60
    else:
        gross_target = 0.35

    valid_n = len(score)
    max_side = valid_n // 2
    if max_side < 1:
        return weights

    desired = int(math.ceil(0.5 * gross_target / 0.02)) if gross_target > 0 else 0
    desired = max(1, desired)
    n_side = min(25, desired, max_side)
    if n_side < 1:
        return weights

    gross = min(gross_target, 0.04 * n_side)
    if gross <= 1e-12:
        return weights

    w = gross / (2.0 * n_side)
    if w > 0.02 + 1e-15:
        w = 0.02
        gross = 2.0 * n_side * w

    sorted_scores = score.sort_values(kind='mergesort')
    longs = list(sorted_scores.index[:n_side])
    shorts = list(sorted_scores.index[-n_side:])

    if set(longs) & set(shorts):
        n_side = min(n_side, valid_n // 2)
        if n_side < 1:
            return weights
        w = gross / (2.0 * n_side)
        longs = list(sorted_scores.index[:n_side])
        shorts = list(sorted_scores.index[-n_side:])

    for t in longs:
        weights.loc[t] = w
    for t in shorts:
        weights.loc[t] = -w

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0)
    weights = weights.clip(-0.02, 0.02)

    gross_actual = weights.abs().sum()
    if gross_actual > 1.0 + 1e-12:
        weights = weights * (1.0 / gross_actual)

    return weights

import numpy as np
import pandas as pd


def _ret_lag(px, start_lag, end_lag, lag):
    if len(px) < start_lag + lag + 1:
        return pd.Series(np.nan, index=px.columns, dtype=float)
    i0 = -1 - lag - start_lag
    i1 = -1 - lag - end_lag
    return px.iloc[i1] / px.iloc[i0] - 1.0


def _mom_best(px, lag, specs):
    for start, end in specs:
        if len(px) >= start + lag + 1:
            return _ret_lag(px, start, end, lag)
    return pd.Series(np.nan, index=px.columns, dtype=float)


def _z_for(series, idx):
    s = series.reindex(idx).astype(float).replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.0, index=idx)
    mu = s.mean(skipna=True)
    sd = s.std(ddof=0, skipna=True)
    if (not np.isfinite(sd)) or sd <= 1e-12:
        return pd.Series(0.0, index=idx)
    z = (s - mu) / sd
    return z.replace([np.inf, -np.inf], np.nan).fillna(0.0).clip(-3.0, 3.0)


def generate_weights(history, universe):
    u = pd.Index(universe)
    w = pd.Series(0.0, index=u, dtype=float)
    if len(u) == 0:
        return w

    ac = history.get('adjusted_close')
    if not isinstance(ac, pd.DataFrame):
        return w

    px = ac.reindex(columns=u).tail(320).astype(float)
    if px.shape[0] < 80:
        return w

    last = px.iloc[-1]
    rets = px.pct_change()
    vol60 = rets.tail(60).std(ddof=0)

    elig = history.get('eligible')
    if isinstance(elig, pd.DataFrame) and len(elig) > 0:
        e = elig.reindex(columns=u).iloc[-1]
        eligible = e.fillna(True).astype(bool)
    else:
        eligible = pd.Series(True, index=u)

    vol_df = history.get('volume')
    has_volume = isinstance(vol_df, pd.DataFrame)
    if has_volume:
        vv = vol_df.reindex(columns=u).reindex(index=px.index)
        dollar = (px * vv).tail(60).median()
    else:
        dollar = pd.Series(np.nan, index=u)

    valid = eligible & last.notna() & np.isfinite(last) & (last > 5.0)
    valid = valid & vol60.notna() & np.isfinite(vol60)
    if has_volume:
        valid = valid & dollar.notna() & (dollar > 0.0)

    if valid.sum() >= 20 and has_volume:
        dv = dollar[valid]
        if dv.notna().sum() >= 20:
            thr = dv.quantile(0.25)
            liq_valid = valid & (dollar >= thr)
            if liq_valid.sum() >= 12:
                valid = liq_valid

    v_idx = valid[valid].index
    if len(v_idx) < 10:
        return w

    mkt_ret = rets.mean(axis=1, skipna=True)
    mkt_price = (1.0 + mkt_ret.fillna(0.0)).cumprod()
    mkt_ma = mkt_price.tail(min(200, len(mkt_price))).mean()
    mkt_trend = float(mkt_price.iloc[-1] / mkt_ma - 1.0) if np.isfinite(mkt_ma) and mkt_ma > 0 else 0.0

    mv = mkt_ret.rolling(20, min_periods=10).std(ddof=0)
    cur_mv = mv.iloc[-1]
    if not np.isfinite(cur_mv) or cur_mv <= 0:
        cur_mv = 0.015
    cur_mv_ann = float(cur_mv * np.sqrt(252.0))
    hist_mv = mv.dropna().tail(200)
    mvol_pct = float((hist_mv <= cur_mv).mean()) if len(hist_mv) >= 20 else 0.5

    ma50 = px.tail(min(50, len(px))).mean()
    breadth = float((last[valid] > ma50[valid]).mean()) if valid.sum() > 0 else 0.5

    if mkt_trend > 0.02 and cur_mv_ann < 0.20 and 0.40 <= breadth <= 0.75:
        rev_w = 0.70
    elif mkt_trend > 0.0 and cur_mv_ann < 0.26 and 0.35 <= breadth <= 0.80:
        rev_w = 0.35
    elif (mkt_trend < -0.04) or (cur_mv_ann > 0.30):
        rev_w = 0.0
    else:
        rev_w = 0.15

    if cur_mv_ann > 0.35:
        gross_target = 0.45
    elif cur_mv_ann > 0.28:
        gross_target = 0.60
    elif cur_mv_ann > 0.22:
        gross_target = 0.80
    else:
        gross_target = 1.0

    if mkt_trend < -0.10 and breadth < 0.35:
        gross_target = min(gross_target, 0.70)
    if mvol_pct > 0.90:
        gross_target = min(gross_target, 0.60)

    ma200 = px.tail(min(200, len(px))).mean()
    trend = last / ma200 - 1.0
    z_trend = _z_for(trend, v_idx)
    vol_for_score = vol60.reindex(u).clip(lower=0.005)

    score_acc = pd.Series(0.0, index=v_idx, dtype=float)
    n_acc = 0
    for lag in (0, 2, 4):
        m12 = _mom_best(px, lag, [(252, 21), (126, 21), (63, 0), (21, 0)])
        m6 = _mom_best(px, lag, [(126, 21), (63, 0), (21, 0)])
        if len(px) >= 22 + lag:
            rev = _ret_lag(px, 21, 0, lag)
        else:
            rev = pd.Series(np.nan, index=u, dtype=float)

        z_m12 = _z_for(m12, v_idx)
        z_m6 = _z_for(m6, v_idx)
        z_rev = _z_for(-rev / vol_for_score, v_idx)

        mom_l = 0.55 * z_m12 + 0.30 * z_m6 + 0.15 * z_trend
        score_l = (1.0 - rev_w) * mom_l + rev_w * z_rev
        score_acc = score_acc + score_l
        n_acc += 1

    if n_acc == 0:
        return w
    score = score_acc / float(n_acc)
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 6:
        return w

    above = (last > ma200).reindex(score.index).fillna(False).astype(bool)
    long_pool = score[above]
    short_pool = score[~above]
    same_pool = False
    if len(long_pool) < 8 or len(short_pool) < 8:
        long_pool = score
        short_pool = score
        same_pool = True

    k = min(40, len(long_pool), len(short_pool))
    if same_pool:
        k = min(k, len(score) // 2)
    if k < 3:
        return w

    longs = list(long_pool.sort_values(ascending=False).index[:k])
    shorts = list(short_pool.sort_values(ascending=True).index[:k])
    if set(longs) & set(shorts):
        k = min(k, len(score) // 2)
        if k < 3:
            return w
        longs = list(score.sort_values(ascending=False).index[:k])
        shorts = list(score.sort_values(ascending=True).index[:k])

    k = min(k, len(longs), len(shorts))
    if k < 1:
        return w
    per_w = min(0.02, 0.5 * gross_target / float(k))

    w.loc[longs[:k]] = per_w
    w.loc[shorts[:k]] = -per_w
    w = w.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)

    gross = float(w.abs().sum())
    if gross > 1.0 and gross > 0:
        w = w * (1.0 / gross)

    return w
